var NOW=Date.now();
var SENT=[['MB5 sent','shradhaa@'],['MB4 sent','akansha@'],['MB3 sent','investors@'],['MB2 sent','dealflow@'],['MB6 sent','admin@']];
var INB=[['MB5 in','shradhaa@'],['MB4 in','akansha@'],['MB3 in','investors@'],['MB2 in','dealflow@'],['MB6 in','admin@']];
function hstr(v){if(!v)return '';if(typeof v==='string')return v;if(v.text)return String(v.text);if(v.value&&v.value[0])return (v.value[0].name?v.value[0].name+' ':'')+'<'+v.value[0].address+'>';return String(v);}
function addrs(s){var m=String(s||'').match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g)||[];var o=[];for(var i=0;i<m.length;i++)o.push(m[i].toLowerCase());return o;}
function one(s){s=String(s||'');var i=s.indexOf('<'),j=s.indexOf('>');if(i>=0&&j>i)return s.slice(i+1,j).trim().toLowerCase();return s.trim().toLowerCase();}
function tsOf(j){var d=j.internalDate||j.date||'';if(/^[0-9]{10,}$/.test(String(d)))return Number(d);var t=Date.parse(d);return isNaN(t)?0:t;}
function ymd(t){if(!t)return '';var d=new Date(t+19800000);return d.toISOString().slice(0,10);}
function norm(s){return String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'');}
function vals(node){var it=[];try{it=$(node).all();}catch(e){return [];}var o=[];for(var i=0;i<it.length;i++){var j=it[i].json||{};if(j.id)o.push(j);}return o;}
function sheet(node){var j={};try{j=$(node).first().json||{};}catch(e){return [];}return j.values||[];}

// --- Gmail sent map: recipient address -> earliest true send ---
var addrSend={},threadSend={},threadSentCount={},sentTotal=0,perBoxSent={},allSent=[];
for(var a=0;a<SENT.length;a++){var nm=SENT[a][0],lbl=SENT[a][1];var ms=vals(nm);perBoxSent[lbl]=ms.length;
 for(var b=0;b<ms.length;b++){var s=ms[b];var st=tsOf(s);if(!st)continue;sentTotal++;
  var subj=String(s.subject||'');
  allSent.push({mb:lbl,id:s.id,thread:s.threadId||'',ts:st,subject:subj.slice(0,120),to:hstr(s.to)});
  if(s.threadId){threadSentCount[s.threadId]=(threadSentCount[s.threadId]||0)+1;var pt=threadSend[s.threadId];if(!pt||pt.ts>st)threadSend[s.threadId]={ts:st,mb:lbl,subject:subj};}
  var tos=addrs(hstr(s.to));
  for(var c=0;c<tos.length;c++){if(tos[c].indexOf('sidanaventures.com')>-1)continue;var pv=addrSend[tos[c]];if(!pv||pv.ts>st)addrSend[tos[c]]={ts:st,mb:lbl,thread:s.threadId||'',subject:subj};}}}

// --- inbound: any external message on a Sidana-subject thread ---
var inThread={},inAddr={},inTotal=0,perBoxIn={};
for(var d2=0;d2<INB.length;d2++){var nm2=INB[d2][0],lb2=INB[d2][1];var mi=vals(nm2);perBoxIn[lb2]=mi.length;
 for(var e2=0;e2<mi.length;e2++){var m2=mi[e2];var fa=one(hstr(m2.from));if(!fa||fa.indexOf('sidanaventures.com')>-1)continue;inTotal++;
  if(m2.threadId)inThread[m2.threadId]=(inThread[m2.threadId]||0)+1;
  inAddr[fa]=(inAddr[fa]||0)+1;}}

// --- ONBOARDING ---
var rows=sheet('Read ONBOARDING');
if(!rows.length)return [{json:{fatal:'ONBOARDING read empty'}}];
var hdr=(rows[0]||[]).map(function(x){return String(x||'').trim().toLowerCase();});
function col(name,fallback){var i=hdr.indexOf(name);return i>=0?i:fallback;}
var C={status:col('status',4),firm:col('firm',5),contact:col('contact',6),email:col('email',8),sector:col('sector_on_file',19),subject:col('subject',24),sent:col('sent_date',27),thread:col('thread_id',28),rr:col('reply_received',29),oc:col('outcome',36),f1:col('fu1_done',38),f1d:col('fu1_date',39),f2:col('fu2_done',40),f2d:col('fu2_date',41)};

// --- INVESTORS do_not_contact ---
var irows=sheet('Read INVESTORS');var ihdr=(irows[0]||[]).map(function(x){return String(x||'').trim().toLowerCase();});
var iDnc=ihdr.indexOf('do_not_contact');var iFirm=ihdr.indexOf('investor_name');if(iFirm<0)iFirm=ihdr.indexOf('firm');if(iFirm<0)iFirm=ihdr.indexOf('name');if(iFirm<0)iFirm=0;
var dncSet={},dncList=[];
if(iDnc>=0){for(var f2=1;f2<irows.length;f2++){var rr2=irows[f2]||[];var v2=String(rr2[iDnc]||'').trim().toLowerCase();if(v2&&v2!=='no'&&v2!=='false'&&v2!=='0'){var fn2=norm(rr2[iFirm]);if(fn2){dncSet[fn2]=String(rr2[iFirm]);dncList.push(String(rr2[iFirm]));}}}}

// --- BOUNCES hard ---
var brows=sheet('Read BOUNCES');var bhdr=(brows[0]||[]).map(function(x){return String(x||'').trim().toLowerCase();});
var bHos=bhdr.indexOf('hard_or_soft');var hardAddr={},hardFirm={},bSample=[];
if(brows.length){for(var g2=1;g2<brows.length;g2++){var br=brows[g2]||[];var hs=bHos>=0?String(br[bHos]||'').trim().toUpperCase():'';if(hs!=='HARD')continue;
  var joined=br.join(' ');var aa=addrs(joined);for(var h2=0;h2<aa.length;h2++)hardAddr[aa[h2]]=1;
  for(var k2=0;k2<br.length;k2++){var cv=String(br[k2]||'');if(cv&&cv.indexOf('@')<0&&cv.length>2&&norm(cv))hardFirm[norm(cv)]=1;}
  if(bSample.length<8)bSample.push(br.slice(0,8));}}

// --- STARTUPS ---
var srows=sheet('Read STARTUPS');var shdr=(srows[0]||[]).map(function(x){return String(x||'').trim().toLowerCase();});
var startups=[];for(var p2=1;p2<srows.length;p2++){var sr=srows[p2]||[];var any=false;for(var q2=0;q2<sr.length;q2++)if(String(sr[q2]||'').trim())any=true;if(!any)continue;var o2={};for(var r3=0;r3<shdr.length;r3++)if(shdr[r3])o2[shdr[r3]]=String(sr[r3]||'');startups.push(o2);}

// --- classify every row ---
var SKIP_STATUS={'HOLD':1,'ONBOARDED':1,'SKIPPED_PRIOR_CONTACT':1,'BOUNCED':1};
var scanned=0,recover=[],noDate=[],due1=[],due2=[],skips={},skipDetail=[];
function skip(cat,o){skips[cat]=(skips[cat]||0)+1;if(skipDetail.length<400)skipDetail.push({cat:cat,row:o.row,firm:o.firm,status:o.status,note:o.note||''});}
for(var i=1;i<rows.length;i++){var r=rows[i]||[];var rowNo=i+1;
 var firm=String(r[C.firm]||'').trim();var contact=String(r[C.contact]||'').trim();
 var emRaw=String(r[C.email]||'');var em=emRaw.split(/[,;]+/).map(function(x){return x.trim().toLowerCase();}).filter(function(x){return x.indexOf('@')>0;});
 if(!firm&&!em.length)continue;scanned++;
 var status=String(r[C.status]||'').trim().toUpperCase();
 var base={row:rowNo,firm:firm,contact:contact,status:status,emails:em};
 if(status!=='SENT'){skip('status_not_SENT:'+(status||'(blank)'),base);continue;}
 if(String(r[C.rr]||'').trim()){skip('has_reply_received',base);continue;}
 if(String(r[C.oc]||'').trim()){skip('has_outcome',{row:rowNo,firm:firm,status:status,note:String(r[C.oc]||'').slice(0,60)});continue;}
 var fnm=norm(firm);
 if(fnm&&dncSet[fnm]){skip('do_not_contact_INVESTORS',base);continue;}
 var dncLoose='';if(fnm&&fnm.length>4){for(var dk in dncSet){if(dk.length>4&&(dk.indexOf(fnm)===0||fnm.indexOf(dk)===0)){dncLoose=dncSet[dk];break;}}}
 if(dncLoose){skip('do_not_contact_INVESTORS_loose',{row:rowNo,firm:firm,status:status,note:'~'+dncLoose});continue;}
 var hb='';for(var x2=0;x2<em.length;x2++)if(hardAddr[em[x2]])hb=em[x2];
 if(!hb&&fnm&&hardFirm[fnm])hb=firm;
 if(hb){skip('hard_bounce',{row:rowNo,firm:firm,status:status,note:hb});continue;}
 // true send date
 var shThread=String(r[C.thread]||'').trim();
 var sheetSent=String(r[C.sent]||'').trim();
 var best=null,src='';
 if(shThread&&threadSend[shThread]){best=threadSend[shThread];src='gmail_thread';}
 if(!best){for(var y2=0;y2<em.length;y2++){var cand=addrSend[em[y2]];if(cand&&(!best||cand.ts>best.ts)){best=cand;src='gmail_addr';}}}
 var sentTs=0,mb='';
 if(best){sentTs=best.ts;mb=best.mb;}
 else{var pd=Date.parse(sheetSent);if(!isNaN(pd)&&sheetSent.length>=8){sentTs=pd;src='sheet_sent_date';}}
 if(!sentTs){noDate.push({row:rowNo,firm:firm,contact:contact,emails:em,sheet_sent_date:sheetSent,thread_id:shThread});continue;}
 var sentYmd=ymd(sentTs);
 if(best&&(!sheetSent||sheetSent.length<8||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(sheetSent)))recover.push({row:rowNo,firm:firm,sheet_was:sheetSent,write:sentYmd,mailbox:mb,src:src});
 // manual reply into the thread?
 var tId=shThread||(best?best.thread:'');
 if(tId&&inThread[tId]){skip('inbound_on_thread',{row:rowNo,firm:firm,status:status,note:'thread '+tId+' has '+inThread[tId]+' external msg'});continue;}
 var inboundAddr=0;for(var z2=0;z2<em.length;z2++)if(inAddr[em[z2]])inboundAddr+=inAddr[em[z2]];
 if(inboundAddr){skip('inbound_from_contact',{row:rowNo,firm:firm,status:status,note:inboundAddr+' msg from '+em.join(',')});continue;}
 if(tId&&threadSentCount[tId]>1){skip('multiple_sent_in_thread',{row:rowNo,firm:firm,status:status,note:threadSentCount[tId]+' sent msgs'});continue;}
 var days=Math.floor((NOW-sentTs)/86400000);
 var f1=String(r[C.f1]||'').trim(),f2v=String(r[C.f2]||'').trim();
 var rec={row:rowNo,firm:firm,contact:contact,emails:em,sector:String(r[C.sector]||''),subject:String(r[C.subject]||''),thread_id:tId,mailbox:mb||'(unknown)',sent_ymd:sentYmd,days:days,date_src:src,fu1_done:f1,fu2_done:f2v,sheet_sent_date:sheetSent};
 if(!f1){if(days>=7)due1.push(rec);else skip('too_early_for_fu1_'+days+'d',{row:rowNo,firm:firm,status:status,note:sentYmd});continue;}
 if(f1&&!f2v){if(days>=20)due2.push(rec);else skip('fu1_done_too_early_for_fu2',{row:rowNo,firm:firm,status:status,note:days+'d'});continue;}
 skip('both_followups_done',base);}

due1.sort(function(a,b){return b.days-a.days;});
due2.sort(function(a,b){return b.days-a.days;});
var sc={};for(var kk in skips)sc[kk]=skips[kk];
return [{json:{today:ymd(NOW),gmail:{sentMessages:sentTotal,perMailboxSent:perBoxSent,distinctRecipientAddrs:Object.keys(addrSend).length,inboundExternal:inTotal,perMailboxInbound:perBoxIn},sheet:{headerCount:hdr.length,colsUsed:C,dataRows:scanned,onboardingHeaderTail:hdr.slice(-8)},tabs:($('Tabs').first().json||{}),investors:{rows:irows.length,dncColumn:iDnc,firmColumn:iFirm,dncCount:dncList.length},bounces:{rows:brows.length,hardOrSoftCol:bHos,hardAddrs:Object.keys(hardAddr).length,hardFirms:Object.keys(hardFirm).length,sample:bSample},startupsCount:startups.length,startupHeaders:shdr,counts:{due_fu1:due1.length,due_fu2:due2.length,no_send_date:noDate.length,sentDatesToRecover:recover.length},skipCounts:sc,due_fu1:due1,due_fu2:due2,no_send_date:noDate,recover:recover,skipDetail:skipDetail,startups:startups}}];
